#[tokio::test]
async fn source_partition_rejects_invalid_filenames_and_legacy_empty_identity() -> anyhow::Result<()> {
    for filename in ["0", "-1", "2147483648", "4294967296", "04613", "+4613", "00000000-0000-0000-0000-000000000001"] {
        let tmp = TempDir::new()?;
        let path = tmp.path().join(format!("{filename}.parquet"));
        write_table::<serde_json::Value>(&path, super::declarations_schema(), &[]).await?;
        let error = super::read_partition(&path).err().expect("invalid source filename");
        assert!(error.to_string().contains("capture a new ingestion run"), "{error}");
    }
    let tmp = TempDir::new()?;
    let path = tmp.path().join("4613.parquet");
    let mut fields = super::declarations_schema().fields().to_vec();
    fields.push(std::sync::Arc::new(arrow::datatypes::Field::new("member_id", arrow::datatypes::DataType::Utf8, false)));
    write_table::<serde_json::Value>(&path, arrow::datatypes::Schema::new(fields), &[]).await?;
    assert!(super::read_partition(&path).err().unwrap().to_string().contains("capture a new ingestion run"));
    Ok(())
}

#[tokio::test]
async fn source_partition_roundtrips_and_rejects_invalid_or_mixed_row_identities() -> anyhow::Result<()> {
    use crate::domain::repositories::entity_ingestion::EntityIngestionStorage;
    let tmp = TempDir::new()?;
    let storage = ExposedDataPipeline::new_with_ingestion_key(&tmp.path().to_path_buf(), IngestionKey::default())?;
    let member = MemberId::new(4613)?;
    let evidence = replay_declaration(json!({"id":42,"category":{"id":3,"name":"Donations"},"versions":[{"register":{"id":820,"publishedDate":"2026-09-07"},"fields":[{"name":"DonorName","value":"Donor"},{"name":"Value","value":"10"}]}]}), chrono::Utc::now())?;
    storage.write_raw_declarations(member, &[evidence.declaration().clone()]).await?;
    let path = storage.raw_path().join("declarations/4613.parquet");
    let capture = super::read_partition(&path)?;
    assert_eq!(capture.member, member);
    assert_eq!(capture.declarations.len(), 1);
    assert_eq!(capture.declarations[0].declaration().id().value(), 42);
    let mut json = arrow::json::ArrayWriter::new(Vec::new());
    let reader = parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder::try_new(std::fs::File::open(&path)?)?.build()?;
    for batch in reader { json.write(&batch?)?; }
    json.finish()?;
    let original: Vec<serde_json::Value> = serde_json::from_slice(&json.into_inner())?;
    assert!(original[0].get("member_id").is_none());
    for (field, value, mixed) in [("parliament_member_id", 0, false), ("parliament_member_id", u32::MAX, false), ("parliament_member_id", 5030, false), ("parliament_member_id", 5030, true), ("declaration_id", 0, false), ("parent_declaration_id", 0, false)] {
        let mut rows = original.clone();
        let mut invalid = original[0].clone();
        invalid[field] = json!(value);
        if mixed { rows.push(invalid); } else { rows[0] = invalid; }
        std::fs::remove_file(&path)?;
        write_table(&path, super::declarations_schema(), &rows).await?;
        assert!(super::read_partition(&path).is_err(), "accepted invalid {field}={value}, mixed={mixed}");
    }
    Ok(())
}
